package com.appnexus.platform.persistence.configuration;

import com.appnexus.platform.configuration.DictionaryManagement;
import com.appnexus.platform.configuration.DictionaryManagementException;
import com.fasterxml.uuid.Generators;
import java.nio.ByteBuffer;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** 字典用例实现；授权锁、层级校验、变更和审计在同一事务完成。 */
@Service
public class MyBatisDictionaryManagement implements DictionaryManagement {
 private final DictionaryMapper mapper;
 public MyBatisDictionaryManagement(DictionaryMapper mapper){this.mapper=mapper;}
 @Override public List<Dictionary> dictionaries(Context context){var c=context(context);if(!mapper.administrator(bytes(c.tenantId()),text(c.actorAccountId()),text(c.actorMemberId())))denied();return mapper.dictionaries(bytes(c.tenantId())).stream().map(this::dictionary).toList();}
 @Override @Transactional public Dictionary createDictionary(Context context,CreateDictionary input){var c=context(context);authority(c);validate(input);UUID id=id();mapper.createDictionary(bytes(c.tenantId()),text(id),input.code().trim(),input.name().trim(),blank(input.description()),input.sortOrder(),text(c.actorAccountId()));mapper.audit(bytes(c.tenantId()),text(id),null,text(c.actorAccountId()),"DICTIONARY_CREATED");return dictionary(mapper.dictionary(bytes(c.tenantId()),text(id)));}
 @Override @Transactional public Dictionary updateDictionary(Context context,UUID dictionaryId,UpdateDictionary input){var c=context(context);authority(c);Objects.requireNonNull(dictionaryId);validate(input);var current=lockedDictionary(c,dictionaryId);if(current.version()!=input.version())conflict();if(mapper.updateDictionary(bytes(c.tenantId()),text(dictionaryId),input.name().trim(),blank(input.description()),input.status().name(),input.sortOrder(),input.version(),text(c.actorAccountId()))!=1)conflict();mapper.audit(bytes(c.tenantId()),text(dictionaryId),null,text(c.actorAccountId()),"DICTIONARY_UPDATED");return dictionary(mapper.dictionary(bytes(c.tenantId()),text(dictionaryId)));}
 @Override @Transactional public void deleteDictionary(Context context,UUID dictionaryId,long version){var c=context(context);authority(c);var current=lockedDictionary(c,Objects.requireNonNull(dictionaryId));validVersion(version);if(current.version()!=version)conflict();if(mapper.dictionaryItemCount(bytes(c.tenantId()),text(dictionaryId))>0)throw error("DICTIONARY_NOT_EMPTY","请先处理字典项");if(mapper.deleteDictionary(bytes(c.tenantId()),text(dictionaryId),version,text(c.actorAccountId()))!=1)conflict();mapper.audit(bytes(c.tenantId()),text(dictionaryId),null,text(c.actorAccountId()),"DICTIONARY_DELETED");}
 @Override public List<Item> items(Context context,UUID dictionaryId){var c=context(context);if(!mapper.administrator(bytes(c.tenantId()),text(c.actorAccountId()),text(c.actorMemberId())))denied();if(mapper.dictionary(bytes(c.tenantId()),text(Objects.requireNonNull(dictionaryId)))==null)notFound();return mapper.items(bytes(c.tenantId()),text(dictionaryId)).stream().map(this::item).toList();}
 @Override @Transactional public Item createItem(Context context,UUID dictionaryId,CreateItem input){var c=context(context);authority(c);lockedDictionary(c,Objects.requireNonNull(dictionaryId));validate(input);parent(c,dictionaryId,input.parentId(),null);UUID id=id();mapper.createItem(bytes(c.tenantId()),text(id),text(dictionaryId),text(input.parentId()),input.code().trim(),input.value().trim(),input.name().trim(),blank(input.description()),input.sortOrder(),text(c.actorAccountId()));mapper.audit(bytes(c.tenantId()),text(dictionaryId),text(id),text(c.actorAccountId()),"ITEM_CREATED");return item(mapper.item(bytes(c.tenantId()),text(dictionaryId),text(id)));}
 @Override @Transactional public Item updateItem(Context context,UUID dictionaryId,UUID itemId,UpdateItem input){var c=context(context);authority(c);lockedDictionary(c,Objects.requireNonNull(dictionaryId));Objects.requireNonNull(itemId);validate(input);var current=lockedItem(c,dictionaryId,itemId);if(current.version()!=input.version())conflict();parent(c,dictionaryId,input.parentId(),itemId);if(mapper.updateItem(bytes(c.tenantId()),text(dictionaryId),text(itemId),text(input.parentId()),input.name().trim(),blank(input.description()),input.status().name(),input.sortOrder(),input.version(),text(c.actorAccountId()))!=1)conflict();mapper.audit(bytes(c.tenantId()),text(dictionaryId),text(itemId),text(c.actorAccountId()),"ITEM_UPDATED");return item(mapper.item(bytes(c.tenantId()),text(dictionaryId),text(itemId)));}
 @Override @Transactional public void deleteItem(Context context,UUID dictionaryId,UUID itemId,long version){var c=context(context);authority(c);lockedDictionary(c,Objects.requireNonNull(dictionaryId));var current=lockedItem(c,dictionaryId,Objects.requireNonNull(itemId));validVersion(version);if(current.version()!=version)conflict();if(mapper.childCount(bytes(c.tenantId()),text(dictionaryId),text(itemId))>0)throw error("DICTIONARY_ITEM_HAS_CHILDREN","存在下级字典项");if(mapper.referenceCount(bytes(c.tenantId()),text(itemId))>0)throw error("DICTIONARY_ITEM_REFERENCED","字典项已被业务引用，请改为停用");if(mapper.deleteItem(bytes(c.tenantId()),text(dictionaryId),text(itemId),version,text(c.actorAccountId()))!=1)conflict();mapper.audit(bytes(c.tenantId()),text(dictionaryId),text(itemId),text(c.actorAccountId()),"ITEM_DELETED");}
 @Override public List<Item> enabledItems(Context context,String code){var c=context(context);code(code);return mapper.enabledItems(bytes(c.tenantId()),code).stream().map(this::item).toList();}

 /** 写操作锁定当前成员的管理授权，避免并发撤权后继续提交配置。 */
 private void authority(Context c){if(mapper.lockAdministrator(bytes(c.tenantId()),text(c.actorAccountId()),text(c.actorMemberId()))==null)denied();}
 private Dictionary lockedDictionary(Context c,UUID id){var row=mapper.lockDictionary(bytes(c.tenantId()),text(id));if(row==null)notFound();return dictionary(row);}
 private Item lockedItem(Context c,UUID dictionary,UUID id){var row=mapper.lockItem(bytes(c.tenantId()),text(dictionary),text(id));if(row==null)notFound();return item(row);}
 /** 通过现有项目内存树验证上级同字典且不会形成循环；数据库复合外键提供第二层保护。 */
 private void parent(Context c,UUID dictionary,UUID parent,UUID self){if(parent==null)return;if(parent.equals(self))throw new IllegalArgumentException("上级不能是自身");var rows=mapper.items(bytes(c.tenantId()),text(dictionary));Map<UUID,UUID> parents=new HashMap<>();for(var r:rows)parents.put(uuid(r,"id"),uuid(r,"parent_id"));if(!parents.containsKey(parent))throw new IllegalArgumentException("上级项不存在");for(UUID cursor=parent;cursor!=null;cursor=parents.get(cursor))if(cursor.equals(self))throw new IllegalArgumentException("字典层级不能成环");}
 private Context context(Context c){Objects.requireNonNull(c);Objects.requireNonNull(c.actorAccountId());Objects.requireNonNull(c.tenantId());Objects.requireNonNull(c.actorMemberId());return c;}
 private void validate(CreateDictionary i){Objects.requireNonNull(i);code(i.code());common(i.name(),i.description(),i.sortOrder());}
 private void validate(UpdateDictionary i){Objects.requireNonNull(i);Objects.requireNonNull(i.status());validVersion(i.version());common(i.name(),i.description(),i.sortOrder());}
 private void validate(CreateItem i){Objects.requireNonNull(i);code(i.code());if(i.value()==null||i.value().isBlank()||i.value().trim().length()>100)throw new IllegalArgumentException("字典值无效");common(i.name(),i.description(),i.sortOrder());}
 private void validate(UpdateItem i){Objects.requireNonNull(i);Objects.requireNonNull(i.status());validVersion(i.version());common(i.name(),i.description(),i.sortOrder());}
 private void code(String v){if(v==null||!v.matches("[a-z][a-z0-9_]{1,63}"))throw new IllegalArgumentException("编码无效");}
 private void common(String n,String d,int s){if(n==null||n.isBlank()||n.trim().length()>100||d!=null&&d.trim().length()>500||s<0||s>9999)throw new IllegalArgumentException("字段无效");}
 private void validVersion(long v){if(v<0)throw new IllegalArgumentException("版本无效");}
 private Dictionary dictionary(Map<String,Object> r){return new Dictionary(uuid(r,"id"),(String)r.get("code"),(String)r.get("name"),(String)r.get("description"),Status.valueOf((String)r.get("status")),number(r,"sort_order").intValue(),number(r,"version").longValue(),instant(r.get("updated_at")));}
 private Item item(Map<String,Object> r){return new Item(uuid(r,"id"),uuid(r,"dictionary_id"),uuid(r,"parent_id"),(String)r.get("code"),(String)r.get("item_value"),(String)r.get("name"),(String)r.get("description"),Status.valueOf((String)r.get("status")),number(r,"sort_order").intValue(),Boolean.TRUE.equals(r.get("referenced"))||number(r,"referenced").intValue()!=0,number(r,"version").longValue(),instant(r.get("updated_at")));}
 private UUID id(){return Generators.timeBasedEpochGenerator().generate();} private UUID uuid(Map<String,Object> r,String k){Object v=r.get(k);return v==null?null:UUID.fromString((String)v);} private Number number(Map<String,Object> r,String k){Object v=r.get(k);return v instanceof Number n?n:0;} private String text(UUID v){return v==null?null:v.toString();} private String blank(String v){return v==null||v.isBlank()?null:v.trim();} private byte[] bytes(UUID v){var b=ByteBuffer.allocate(16);b.putLong(v.getMostSignificantBits()).putLong(v.getLeastSignificantBits());return b.array();} private Instant instant(Object v){if(v instanceof Instant i)return i;if(v instanceof Timestamp t)return t.toInstant();if(v instanceof LocalDateTime t)return t.toInstant(ZoneOffset.UTC);throw new IllegalStateException("Unsupported timestamp");}
 private void denied(){throw new SecurityException("Dictionary management authority required");} private void notFound(){throw error("DICTIONARY_NOT_FOUND","字典或字典项不存在");} private void conflict(){throw error("DICTIONARY_VERSION_CONFLICT","字典已被其他管理员修改");} private DictionaryManagementException error(String c,String m){return new DictionaryManagementException(c,m);}
}
